//! GDT, TSS, IDT and trap entry.
//!
//! Every vector has a 16-byte entry stub (generated by the assembler in
//! `entry.rs`) that normalizes the stack to a [`TrapFrame`] and calls
//! [`trap_dispatch`]. Double faults, NMIs and machine checks run on their
//! own IST stacks, so a kernel stack overflow (which faults on the guard
//! page) is still reported. The CPU reaches the IDT, GDT, TSS and every
//! stack it switches to through the entry area (ADR-0004 §2).

use alloc::boxed::Box;
use core::arch::asm;
use core::sync::atomic::{AtomicU64, Ordering::Relaxed};

use super::{entry, regs};
use crate::mm::kspace::STACK_PAGES;
use crate::mm::{PAGE_SIZE, STACKS_BASE};

pub(crate) const KERNEL_CS: u16 = 0x08;
pub(crate) const KERNEL_SS: u16 = 0x10;
const TSS_SEL: u16 = 0x28;

const IST_DOUBLE_FAULT: u8 = 1;
const IST_NMI: u8 = 2;
const IST_MACHINE_CHECK: u8 = 3;

/// First vector used for interrupts (below are CPU exceptions).
pub(crate) const FIRST_IRQ_VECTOR: u8 = 32;

/// Register state saved on every trap. Layout matches the entry stubs.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct TrapFrame {
    pub rax: u64,
    pub rbx: u64,
    pub rcx: u64,
    pub rdx: u64,
    pub rsi: u64,
    pub rdi: u64,
    pub rbp: u64,
    pub r8: u64,
    pub r9: u64,
    pub r10: u64,
    pub r11: u64,
    pub r12: u64,
    pub r13: u64,
    pub r14: u64,
    pub r15: u64,
    pub vector: u64,
    pub error_code: u64,
    pub rip: u64,
    pub cs: u64,
    pub rflags: u64,
    pub rsp: u64,
    pub ss: u64,
}

// The trap stubs and their shared tail are entry code (`entry.rs`): every
// gate points at a stub's entry-area alias.

/// The IDT, shared by every CPU. Each gate is two quadwords. It fills its
/// own page, which the entry area aliases (the CPU reads it through the
/// alias, user root or not).
#[repr(C, align(4096))]
struct Idt([AtomicU64; 512]);

static IDT: Idt = Idt([const { AtomicU64::new(0) }; 512]);

fn set_gate(vector: u8, ist: u8) {
    let addr = entry::stub(vector);
    // Present, 64-bit interrupt gate; `int 3` and `into` are the only ones
    // ring 3 may raise by instruction (debuggers' and `abort`'s breakpoint).
    let kind = if matches!(vector, 3 | 4) { 0xee } else { 0x8e };
    let low = (addr & 0xffff)
        | (u64::from(KERNEL_CS) << 16)
        | (u64::from(ist) << 32)
        | (kind << 40)
        | ((addr >> 16) & 0xffff) << 48;
    IDT.0[vector as usize * 2].store(low, Relaxed);
    IDT.0[vector as usize * 2 + 1].store(addr >> 32, Relaxed);
}

/// Maps the entry code and the IDT into the entry area and fills the IDT.
/// Runs once, on the boot CPU. `None` if memory for the mapping runs out.
pub(crate) fn init_idt() -> Option<()> {
    entry::map_shared(core::ptr::addr_of!(IDT) as u64)?;
    for v in 0..=255u8 {
        let ist = match v {
            8 => IST_DOUBLE_FAULT,
            2 => IST_NMI,
            18 => IST_MACHINE_CHECK,
            _ => 0,
        };
        set_gate(v, ist);
    }
    Some(())
}

#[repr(C, packed(4))]
#[derive(Default)]
struct Tss {
    reserved0: u32,
    rsp: [u64; 3],
    reserved1: u64,
    ist: [u64; 7],
    reserved2: u64,
    reserved3: u16,
    iomap_base: u16,
}

/// One CPU's GDT and TSS, alone in a page the entry area aliases. Leaked:
/// CPUs never go away.
#[repr(C, align(4096))]
struct CpuTables {
    gdt: [u64; 7],
    tss: Tss,
}

#[repr(C, packed(2))]
struct DescriptorPointer {
    limit: u16,
    base: u64,
}

/// Builds this CPU's part of the entry area, points GS at its block's
/// alias there, and loads its GDT and TSS (RSP0 at the entry stack, IST
/// stacks) and the shared IDT, all through their aliases. Returns `None`
/// if memory runs out.
pub(crate) fn init_cpu() -> Option<()> {
    let tables = Box::new(CpuTables {
        gdt: [
            0,
            0x00af_9a00_0000_ffff, // 0x08 kernel code (64-bit)
            0x00cf_9200_0000_ffff, // 0x10 kernel data
            0x00cf_f200_0000_ffff, // 0x18 user data
            0x00af_fa00_0000_ffff, // 0x20 user code (64-bit)
            0,
            0, // 0x28 TSS (two slots)
        ],
        tss: Tss {
            iomap_base: core::mem::size_of::<Tss>() as u16, // no I/O bitmap
            ..Tss::default()
        },
    });
    let tables: &'static mut CpuTables = Box::leak(tables);
    let block = crate::cpu::this_block();
    let index = block.index.load(Relaxed) as usize;
    let area = entry::map_cpu(index, block, core::ptr::from_ref(tables) as u64)?;
    for ist in [IST_DOUBLE_FAULT, IST_NMI, IST_MACHINE_CHECK] {
        let i = usize::from(ist - 1);
        tables.tss.ist[i] = area.ist[i];
    }
    tables.tss.rsp[0] = entry::entry_stack(block);
    let tss = area.tables + core::mem::offset_of!(CpuTables, tss) as u64;
    let limit = core::mem::size_of::<Tss>() as u64 - 1;
    tables.gdt[5] = (limit & 0xffff)
        | ((tss & 0xff_ffff) << 16)
        | (0x89 << 40) // present, 64-bit available TSS
        | (((tss >> 24) & 0xff) << 56);
    tables.gdt[6] = tss >> 32;
    let tables: &'static CpuTables = tables;
    super::set_cpu_block(area.block);

    let gdt = DescriptorPointer {
        limit: (core::mem::size_of_val(&tables.gdt) - 1) as u16,
        base: area.tables,
    };
    let idt = DescriptorPointer {
        limit: (core::mem::size_of_val(&IDT) - 1) as u16,
        base: entry::IDT,
    };
    // SAFETY: `gdt` describes the entry-area alias of a 'static GDT whose
    // code/data selectors match `KERNEL_CS`/`KERNEL_SS`; CS is reloaded with
    // a far return to the next instruction and the data segments with the
    // kernel data selector; the TSS descriptor points at the alias of a
    // 'static TSS whose stacks are mapped; `idt` is the alias of the filled
    // IDT. FS/GS are left alone: in 64-bit mode only their MSR-held bases
    // matter, and reloading GS would clear the per-CPU block pointer.
    unsafe {
        asm!(
            "lgdt [{gdt}]",
            "push {cs}",
            "lea {tmp}, [rip + 2f]",
            "push {tmp}",
            "retfq",
            "2:",
            "mov {tmp:e}, {ss}",
            "mov ss, {tmp:e}",
            "mov ds, {tmp:e}",
            "mov es, {tmp:e}",
            "mov {tmp:e}, {tss}",
            "ltr {tmp:x}",
            "lidt [{idt}]",
            gdt = in(reg) &gdt,
            idt = in(reg) &idt,
            cs = const KERNEL_CS as u64,
            ss = const KERNEL_SS as u32,
            tss = const TSS_SEL as u32,
            tmp = out(reg) _,
        )
    };
    Some(())
}

const EXCEPTION_NAMES: [&str; 32] = [
    "divide error",
    "debug",
    "NMI",
    "breakpoint",
    "overflow",
    "bound range exceeded",
    "invalid opcode",
    "device not available",
    "double fault",
    "coprocessor segment overrun",
    "invalid TSS",
    "segment not present",
    "stack-segment fault",
    "general protection fault",
    "page fault",
    "reserved",
    "x87 floating-point error",
    "alignment check",
    "machine check",
    "SIMD floating-point error",
    "virtualization exception",
    "control protection exception",
    "reserved",
    "reserved",
    "reserved",
    "reserved",
    "reserved",
    "reserved",
    "hypervisor injection exception",
    "VMM communication exception",
    "security exception",
    "reserved",
];

static BREAKPOINTS: AtomicU64 = AtomicU64::new(0);

/// Breakpoint exceptions handled so far.
pub(crate) fn breakpoint_count() -> u64 {
    BREAKPOINTS.load(Relaxed)
}

fn in_stack_guard(addr: u64) -> bool {
    let slot = (STACK_PAGES + 1) * PAGE_SIZE;
    addr >= STACKS_BASE && (addr - STACKS_BASE) % slot < PAGE_SIZE
}

/// Handles a trap. One from ring 3 is always recorded into the thread's
/// context, and the entry code then returns into `UserMode::execute`
/// (`ichor_trap_common`); the return value is 1 then, else 0.
#[allow(clippy::panic)] // Unexpected kernel exceptions are kernel bugs.
pub(super) extern "sysv64" fn trap_dispatch(f: &mut TrapFrame) -> u64 {
    let vector = f.vector as u8;
    let from_user = f.cs & 3 == 3;
    // An exception taken in ring 3 (not an interrupt, not NMI) is recorded
    // into the thread's context and ends the user run. We must not panic on
    // it: user code faulting is routine.
    if from_user && vector < 32 && vector != 2 {
        super::usermode::record_user_trap(f);
        return 1;
    }
    match vector {
        3 => {
            BREAKPOINTS.fetch_add(1, Relaxed);
        }
        2 => super::apic::handle_nmi(),
        FIRST_IRQ_VECTOR..=255 => {
            super::apic::handle_irq(vector, f);
            if from_user {
                // `execute` holds a guard for the whole user run, so the
                // task cannot be preempted here; end the run instead and let
                // the caller yield.
                if crate::task::resched_pending() {
                    super::usermode::record_user_preempt(f);
                    return 1;
                }
            } else if f.rflags & (1 << 9) != 0 {
                // Preempt only code that ran with interrupts enabled (so it
                // held no guard and no spinlock).
                crate::task::preempt_point();
            }
        }
        14 => {
            let addr = regs::read_cr2();
            let what = if in_stack_guard(addr) {
                " (kernel stack overflow)"
            } else {
                ""
            };
            panic!(
                "page fault at {addr:#x}{what}: error {:#x} at rip {:#x}",
                f.error_code, f.rip
            );
        }
        8 => {
            // A kernel stack overflow faults on the guard page, and pushing
            // the #PF frame onto the same stack faults again: a #DF. CR2
            // still holds the guard address. The rsp alone is not enough: a
            // faulting `push` leaves it just above the guard.
            let what = if in_stack_guard(f.rsp) || in_stack_guard(regs::read_cr2()) {
                " (kernel stack overflow)"
            } else {
                ""
            };
            panic!("double fault{what} at rip {:#x}, rsp {:#x}", f.rip, f.rsp);
        }
        _ => panic!(
            "{} (vector {vector}, error {:#x}) at rip {:#x}",
            EXCEPTION_NAMES.get(vector as usize).copied().unwrap_or("?"),
            f.error_code,
            f.rip
        ),
    }
    if from_user {
        // An NMI or an interrupt that needs no reschedule: `execute` goes
        // straight back to ring 3.
        super::usermode::record_user_interrupt(f);
        return 1;
    }
    0
}

/// Executes `int3`; frame's handler counts it and returns.
pub(crate) fn breakpoint() {
    // SAFETY: the IDT is installed and the breakpoint handler returns
    // normally, restoring every register.
    unsafe { asm!("int3", options(nomem, nostack)) };
}
